       SUM(day.discard) discard, SUM(day.ret_pv) ret_pv, SUM(day.spend) spend, SUM(day.income) income,
       SUM(day.discount_click_pv) discount_click_pv, SUM(day.discount_show_pv) discount_show_pv,
       SUM(day.dplsucc_pv) dplsucc_pv, SUM(day.complete_pv) complete_pv,
       SUM(day.install_pv) install_pv, SUM(day.activate_pv) activate_pv
FROM data_ssp_slot_day day
LEFT JOIN ssp_slot_info ssp ON day.ssp_slot_id = ssp.id
LEFT JOIN ssp_app app ON app.id = ssp.app_id

    day.date BETWEEN #{reqVO.date[0]} AND #{reqVO.date[1]}
