UPDATE data_ssp_slot_day
SET income = #{income}, spend = #{spend}
WHERE ssp_slot_id = #{sspSlotId}
  AND dsp_slot_code = #{dspSlotCode}
  AND date = #{date}

UPDATE data_ssp_slot_day
SET spend = #{spend},
    income = #{income}
WHERE dsp_slot_code = #{dspSlotCode}
  AND dsp_slot_id = #{dspSlotId}
  AND ssp_slot_id = #{sspSlotId}
  AND date = #{date}
  AND deleted = 0
